function sleep(ms){return new Promise(r=>setTimeout(r,ms))}
function safeName(n){const special={'Mr. Rime':'mrrime','Mime Jr.':'mimejr','Farfetch’d':'farfetchd','Sirfetch’d':'sirfetchd','Nidoran♀':'nidoranf','Nidoran♂':'nidoranm','Ho-Oh':'hooh','Porygon-Z':'porygonz','Jangmo-o':'jangmoo','Hakamo-o':'hakamoo','Kommo-o':'kommoo'};return special[n]||n.replace(/[’']/g,'').replace(/[^a-zA-Z0-9]+/g,'').toLowerCase()}
