  if(mon.bondActive) return dir+'greninja-ash.gif';
  if(mon.form==='mega-x' || (mon.originalName==='Charizard' && mon.item==='Charizardite X' && mon.form==='mega')) return mon.shiny ? (back?'https://play.pokemonshowdown.com/sprites/ani-back-shiny/':'https://play.pokemonshowdown.com/sprites/ani-shiny/')+'charizard-megax.gif' : dir+'charizard-megax.gif';
  if(mon.form==='mega') return mon.shiny ? (back?'https://play.pokemonshowdown.com/sprites/ani-back-shiny/':'https://play.pokemonshowdown.com/sprites/ani-shiny/')+safeName(mon.originalName)+'-mega.gif' : dir+safeName(mon.originalName)+'-mega.gif';
