function cloneMon(def,side){
  const b=base[def.name]||[70,70,70,70,70,70];
  const ev={hp:0,atk:0,def:0,spa:0,spd:0,spe:0,...(def.ev||{})};
  const nat=natures[def.nature]||{};
  const calc=(idx,key)=>{const raw=b[idx];const val=Math.floor(((2*raw+31+Math.floor(ev[key]/4))*70)/100)+5;return Math.floor(val*(nat[key]||1))};
  const hp=Math.floor(((2*b[0]+31+Math.floor(ev.hp/4))*70)/100)+70+10;
  return {...def,types:[...(types[def.name]||[])].map(canonType),base:[...b],ev,hp,maxHp:hp,atk:calc(1,'atk'),def:calc(2,'def'),spa:calc(3,'spa'),spd:calc(4,'spd'),spe:calc(5,'spe'),fainted:false,status:null,statusTurns:0,protect:false,side,originalName:def.name,
    mega:!!def.mega,gmax:!!def.gmax||((side==='player'?playerTrainer:opponentTrainer)==='Ash'&&def.name==='Pikachu'),zmove:((side==='player'?playerTrainer:opponentTrainer)==='Ash'&&def.name==='Pikachu'),bondAvailable:!!def.bond||def.ability==='Battle Bond',bondActive:false,megaUsed:false,gmaxUsed:false,bondUsed:false,statStages:{atk:0,def:0,spa:0,spd:0,spe:0},gimmickUsed:false,policyUsed:false,sitrusUsed:false,liechiUsed:false,sashUsed:false,itemConsumed:false,recharge:0,chargingMove:null,leechSeeded:false,originalMoves:[...(def.moves||[])],gmaxTurns:0,zUsed:false,ability:def.ability};
}
function teamFrom(list,side){return (list||[]).map(x=>cloneMon(x,side))}
function canonType(t){const x=String(t||'Normal').trim().toLowerCase();const map={normal:'Normal',fire:'Fire',water:'Water',electric:'Electric',grass:'Grass',ice:'Ice',fighting:'Fighting',poison:'Poison',ground:'Ground',flying:'Flying',psychic:'Psychic',bug:'Bug',rock:'Rock',ghost:'Ghost',dragon:'Dragon',dark:'Dark',steel:'Steel',fairy:'Fairy'};return map[x]||'Normal'}
function eff(type,defTypes){const atk=canonType(type);return (defTypes||[]).reduce((v,t)=>v*(chart[atk]?.[canonType(t)]??1),1)}
function effectivenessText(e){if(e===4)return 'EXTREMELY EFFECTIVE ×4';if(e===2)return 'SUPER EFFECTIVE ×2';if(e===1)return 'EFFECTIVE ×1';if(e===0)return 'NO EFFECT ×0';if(e===.25)return 'NOT VERY EFFECTIVE ×¼';return 'NOT VERY EFFECTIVE ×½'}
