  $('playerGrid').innerHTML=trainers.map(n=>`<div class="card trainer-select" data-trainer="${n}">${cardImageForTrainer(n)}<h3>${n}</h3><p>${trainerDesc[n]}</p><span class="badge">PLAY AS ${n.toUpperCase()}</span></div>`).join('');
