function chooseEnemyMove(e,p){const usable=(e.moves||[]).filter(n=>moves[n]&&moves[n][2]!=='status'&&moves[n][1]>0);if(!usable.length)return (e.moves||[])[0]||'Tackle';return usable.sort((a,b)=>{const A=moves[a],B=moves[b];const sa=(A[1]||0)*typeMultiplier(A,p)*(A[3]===true?1:A[3]/100);const sb=(B[1]||0)*typeMultiplier(B,p)*(B[3]===true?1:B[3]/100);return sb-sa})[0]}
async function enemyGimmick(){const e=enemy[ei];if(!e||e.fainted||e.gimmickUsed||turn<2)return false;if(e.mega&&Math.random()<.3){e.gimmickUsed=true;e.megaUsed=true;e.form='mega';e.name='Mega '+e.originalName;if(e.originalName==='Metagross')e.ability='Tough Claws';if(e.originalName==='Garchomp')e.ability='Sand Force';if(e.originalName==='Gardevoir')e.ability='Pixilate';if(e.originalName==='Charizard'&&e.item==='Charizardite X'){e.form='mega-x';e.name='Mega Charizard X';e.types=['Fire','Dragon'];e.ability='Tough Claws';}setMessage(`${opponentTrainer} Mega Evolved ${e.originalName}!`,1500);animateBattle('enemy','special');await sleep(850);return true}if(e.gmax&&Math.random()<.3){e.gimmickUsed=true;e.gmaxUsed=true;e.gmaxActive=true;e.gmaxTurns=3;if(e.originalName==='Charizard')e.moves=['G-Max Wildfire','Max Airstream','Max Rockfall','Max Wyrmwind'];if(e.originalName==='Gengar')e.moves=['G-Max Terror','Max Ooze','Max Starfall','Max Flare'];if(e.originalName==='Pikachu')e.moves=['G-Max Volt Crash','Max Steelspike','Max Strike','Max Strike'];setMessage(`${opponentTrainer} Gigantamaxed ${e.originalName}!`,1500);animateBattle('enemy','special');await sleep(850);return true}return false}
function animateBattle(side,type){const el=$(side==='player'?'playerSprite':'enemySprite');if(!el)return;el.classList.remove('attack-anim','hit-anim','faint-anim','special-anim');void el.offsetWidth;el.classList.add(type==='special'?'special-anim':type==='hit'?'hit-anim':type==='faint'?'faint-anim':'attack-anim');setTimeout(()=>el.classList.remove('attack-anim','hit-anim','faint-anim','special-anim'),850)}
